function rng(s) { return () => (s = (s * 1664525 + 1013904223) % 4294967296) / 4294967296; }
const SEED = (() => {
  const r = rng(7), pick = a => a[Math.floor(r() * a.length)], out = []; let n = 0;
  PROGRAMS.forEach(p => {
    const lv = BACH.has(p.name) ? LEVELS : LEVELS.slice(0, 2);
    lv.forEach(level => ["2565", "2566", "2567"].forEach(year => {
      const k = level === "ป.ตรี" ? 1 + Math.floor(r() * 2) : 2 + Math.floor(r() * 3);
      for (let i = 0; i < k; i++) {
        n++; const x = r();
        const status = x < .62 ? "employed" : x < .8 ? "study" : x < .86 ? "business" : x < .97 ? "unemployed" : "other";
        const g = { id: "64" + String(100000 + n).padStart(8, "0"), name: pick(FN) + " " + pick(LN), dept: p.name, level, year, status, province: pick(PROV),
          phone: `08${Math.floor(r() * 10)}-${Math.floor(r() * 900) + 100}-${Math.floor(r() * 9000) + 1000}` };
        if (status === "employed") { const b = level === "ปวช." ? 11000 : level === "ปวส." ? 15000 : 20000; g.company = pick(CO[p.key]); g.salary = Math.round((b + r() * 7000) / 100) * 100; g.related = r() < .82; }
        if (status === "study") g.school = pick(SCH);
        if (status === "other") g.otherDetail = pick(OTH);
        out.push(g);
      }
    }));
  });
  return out;
})();

const detail = g => g.status === "employed" ? `${g.company || "-"}${g.position ? " · " + g.position : ""} · ${(g.salary || 0).toLocaleString()} บ.` : g.status === "study" ? `${g.school || "-"}${g.faculty ? " · " + g.faculty : ""}` : g.status === "unemployed" ? (g.jobStatus === "ยังไม่ต้องการทำงาน" ? "ยังไม่ต้องการทำงาน" : `หางาน${g.jobInterest ? " · สนใจ " + g.jobInterest : ""}${g.needHelp ? " · ต้องการให้ช่วย" : ""}`) : g.status === "business" ? (g.bizName ? `${g.bizName}${g.bizType ? " (" + g.bizType + ")" : ""}` : "ประกอบธุรกิจส่วนตัว") : (g.otherDetail || "อื่นๆ");
function useWidth() {
  const [w, setW] = useState(typeof window === "undefined" ? 1200 : window.innerWidth);
  useEffect(() => { const f = () => setW(window.innerWidth); window.addEventListener("resize", f); return () => window.removeEventListener("resize", f); }, []);
  return w;
}
const pct = (a, b) => b ? Math.round(a / b * 100) : 0;
const tip = { contentStyle: { ...S, borderRadius: 12, border: `1px solid ${C.line}` } };
const tick = { fontSize: 11, fontFamily: "Sarabun", fill: C.soft };

// ---------- ภาพนักศึกษาประจำสาขา (ภาพประกอบ + ช่องใส่รูปจริง) ----------
