const PHOTO_URLS = {};
const ICONS = { "ช่างยนต์": Car, "ช่างกลโรงงาน": Cog, "ช่างเชื่อมโลหะ": Flame, "ช่างไฟฟ้ากำลัง": Zap, "ช่างอิเล็กทรอนิกส์": Cpu, "ช่างก่อสร้าง": HardHat, "ช่างโยธา": Ruler, "เทคนิคคอมพิวเตอร์": Monitor, "แมคคาทรอนิกส์": Bot, "การบัญชี": Calculator, "การตลาด": Megaphone, "การเลขานุการ": ClipboardList, "คอมพิวเตอร์ธุรกิจ": Laptop, "ธุรกิจค้าปลีก": ShoppingBag, "เทคโนโลยีสารสนเทศ": Code2, "การโรงแรม": ConciergeBell };
const SKIN = ["#F6D2B0", "#E9B98E", "#D9A074"], HAIR = "#2B1F1A";
function Student({ name }) {
  const i = Math.max(0, PROGRAMS.findIndex(p => p.name === name)), p = PROGRAMS[i], col = colorOf(name), skin = SKIN[i % 3], girl = i % 2 === 1;
  const shirt = { ind: "#2F5DA8", biz: "#F4F7F5", it: "#3B3F6B", hotel: "#8E2A4F" }[p.key];
  return (
    <svg viewBox="0 0 120 120" width="100%" height="100%" style={{ display: "block" }}>
      <defs><linearGradient id={`sg${i}`} x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor={col} stopOpacity=".25" /><stop offset="1" stopColor={col} stopOpacity=".65" /></linearGradient></defs>
      <rect width="120" height="120" fill={`url(#sg${i})`} />
      <circle cx="96" cy="24" r="14" fill="#fff" opacity=".25" /><circle cx="18" cy="40" r="8" fill="#fff" opacity=".2" />
      {girl && <path d="M34 62c-4-30 12-42 26-42s30 12 26 42c0 14 4 26 0 34H34c-4-8 0-20 0-34z" fill={HAIR} />}
      <path d="M16 120c2-27 21-37 44-37s42 10 44 37z" fill={shirt} />
      <path d="M49 84l11 15 11-15z" fill={p.key === "biz" ? "#DCE6E0" : "#fff"} />
      {p.key === "biz" && <path d="M57 90h6l3 20-6 5-6-5z" fill="#E0457B" />}
      <rect x="53" y="68" width="14" height="18" rx="6" fill={skin} />
      <ellipse cx="60" cy="52" rx="19" ry="22" fill={skin} />
      <path d={girl ? "M40 50c0-16 9-25 20-25s20 9 20 25c-8-3-14-9-17-14-3 7-11 12-23 14z" : "M40 48c-2-18 8-26 20-26s22 8 20 26c-4-6-8-10-12-12-8 4-20 4-28 12z"} fill={HAIR} />
      <circle cx="52" cy="55" r="2.2" fill="#2B1F1A" /><circle cx="68" cy="55" r="2.2" fill="#2B1F1A" />
      <circle cx="47" cy="62" r="3.5" fill="#F58AA8" opacity=".35" /><circle cx="73" cy="62" r="3.5" fill="#F58AA8" opacity=".35" />
      <path d="M53 63q7 6 14 0" stroke="#B5533C" strokeWidth="2" fill="none" strokeLinecap="round" />
      {p.key === "ind" && <><path d="M38 44c0-15 10-24 22-24s22 9 22 24z" fill="#FFC832" /><rect x="33" y="42" width="54" height="5" rx="2.5" fill="#F0A800" /><rect x="56" y="20" width="8" height="10" rx="3" fill="#F0A800" /></>}
      {p.key === "it" && <><path d="M39 54c-2-22 8-31 21-31s23 9 21 31" stroke="#222" strokeWidth="4" fill="none" /><rect x="35" y="50" width="7" height="14" rx="3" fill={col} /><rect x="78" y="50" width="7" height="14" rx="3" fill={col} /></>}
      {p.key === "hotel" && <><rect x="72" y="94" width="18" height="10" rx="2" fill="#fff" /><rect x="75" y="97" width="12" height="2" fill={col} /></>}
    </svg>
  );
}
const Portrait = ({ name, photos }) => { const src = photos?.[name] || PHOTO_URLS[name]; return src ? <img src={src} alt={name} className="w-full h-full object-cover" /> : <Student name={name} />; };
function ProgramAvatar({ name, photos, size = 56 }) {
  const Ic = ICONS[name] || Briefcase, col = colorOf(name);
  return (
    <div className="relative flex-shrink-0" style={{ width: size, height: size }}>
      <div className="w-full h-full rounded-2xl overflow-hidden" style={{ boxShadow: `0 0 0 2px #fff, 0 0 0 4px ${col}55` }}><Portrait name={name} photos={photos} /></div>
      <span className="absolute rounded-full flex items-center justify-center" style={{ right: -4, bottom: -4, width: size * .4, height: size * .4, background: col, border: "2px solid #fff" }}><Ic size={size * .22} color="#fff" /></span>
    </div>
  );
}
function readPhoto(file, cb) {
  const r = new FileReader();
  r.onload = () => { const img = new Image(); img.onload = () => { const k = Math.min(1, 640 / Math.max(img.width, img.height)), c = document.createElement("canvas"); c.width = img.width * k; c.height = img.height * k; c.getContext("2d").drawImage(img, 0, 0, c.width, c.height); cb(c.toDataURL("image/jpeg", .85)); }; img.src = r.result; };
  r.readAsDataURL(file);
}
function PhotoUpload({ dept, onPhoto, light }) {
  return (
    <label className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium cursor-pointer" style={{ background: light ? "#ffffff30" : C.card, color: light ? "#fff" : C.ink, border: light ? "none" : `1px solid ${C.line}`, ...S }}>
      <Camera size={13} />อัปโหลดรูปประจำสาขา
      <input type="file" accept="image/*" className="hidden" onChange={e => { const f = e.target.files?.[0]; if (f) readPhoto(f, u => onPhoto(dept, u)); e.target.value = ""; }} />
    </label>
  );
}

// โลโก้คู่: สอศ. (อันแรก) ตามด้วยวิทยาลัยเทคนิคฉะเชิงเทรา
